--
-- Структура таблицы `rolestate`
--

CREATE TABLE `rolestate` (
  `roleId` bigint(20) NOT NULL COMMENT '角色ID值',
  `userId` bigint(20) DEFAULT NULL COMMENT '账号ID值',
  `roleName` varchar(50) DEFAULT NULL COMMENT '角色名',
  `machineCode` varchar(70) DEFAULT NULL COMMENT '机器码',
  `platUserId` varchar(128) DEFAULT NULL COMMENT '渠道ID',
  `clientOS` varchar(30) DEFAULT NULL COMMENT '客户端系统',
  `level` int(11) DEFAULT NULL COMMENT '等级',
  `sex` int(4) DEFAULT NULL COMMENT '性别',
  `career` int(4) DEFAULT NULL COMMENT '角色职业',
  `createTime` varchar(50) DEFAULT NULL COMMENT '创建时间',
  `onlineTime` int(11) DEFAULT NULL COMMENT '在线时长',
  `createsid` int(11) DEFAULT NULL COMMENT '创建服ID',
  `attack` bigint(20) DEFAULT NULL COMMENT '攻击力',
  `lastupdatetime` varchar(50) DEFAULT NULL COMMENT '更新的最新时间值',
  `ts` int(11) NOT NULL COMMENT '更新的最新秒值',
  `bagcellsnum` int(11) DEFAULT NULL COMMENT '背包格子数量',
  `ip` varchar(50) DEFAULT NULL COMMENT '当前登录IP',
  `money` bigint(20) DEFAULT NULL COMMENT '铜币',
  `gold` bigint(20) DEFAULT NULL COMMENT '元宝',
  `iron` bigint(20) DEFAULT NULL COMMENT '体力',
  `isDelete` int(11) DEFAULT NULL COMMENT '是否删除',
  `rechargeGold` bigint(20) DEFAULT NULL COMMENT '总充值获得元宝数',
  `funcellUUid` varchar(64) DEFAULT NULL COMMENT 'funcell生成的UUid',
  `platformName` varchar(50) DEFAULT NULL COMMENT '渠道',
  `horseLayer` int(11) DEFAULT NULL COMMENT '坐骑等级',
  `horseIllusionLevel` int(11) DEFAULT NULL COMMENT '坐骑等级',
  `horseIds` varchar(300) DEFAULT NULL COMMENT '所有坐骑Id集',
  `wingIds` varchar(300) DEFAULT NULL COMMENT '所有翅膀Id集',
  `petIds` varchar(300) DEFAULT NULL COMMENT '所有宠物Id集',
  `clotheStar` int(11) DEFAULT NULL COMMENT '衣服星级',
  `weaponStar` int(11) DEFAULT NULL COMMENT '武器星级',
  `equipAllStar` int(11) DEFAULT NULL COMMENT '穿戴装备总星级',
  `moonCardDay` int(11) DEFAULT NULL COMMENT '玩家的月卡结束天数',
  `isRecharge` int(11) DEFAULT NULL COMMENT '角色是否有充过值',
  `lastLoginTime` int(11) DEFAULT NULL COMMENT '最后一次登录时间',
  `fashionBodyId` int(11) DEFAULT NULL COMMENT '时装身体ID',
  `fashionWeaponId` int(11) DEFAULT NULL COMMENT '时装武器ID',
  `lifeCard` int(11) DEFAULT NULL COMMENT '是否激活终身卡',
  `clearlevel` int(11) DEFAULT NULL COMMENT '清理等级',
  `cpUserId` varchar(64) DEFAULT NULL COMMENT '平台账号ID'
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci ROW_FORMAT=COMPACT;

--
-- Дамп данных таблицы `rolestate`
--

INSERT INTO `rolestate` (`roleId`, `userId`, `roleName`, `machineCode`, `platUserId`, `clientOS`, `level`, `sex`, `career`, `createTime`, `onlineTime`, `createsid`, `attack`, `lastupdatetime`, `ts`, `bagcellsnum`, `ip`, `money`, `gold`, `iron`, `isDelete`, `rechargeGold`, `funcellUUid`, `platformName`, `horseLayer`, `horseIllusionLevel`, `horseIds`, `wingIds`, `petIds`, `clotheStar`, `weaponStar`, `equipAllStar`, `moonCardDay`, `isRecharge`, `lastLoginTime`, `fashionBodyId`, `fashionWeaponId`, `lifeCard`, `clearlevel`, `cpUserId`) VALUES
